#include <iostream>
#include <sstream>
#include <string>
using namespace std;

class QueryBuilder {
    ostringstream oss;
public:
    QueryBuilder& select(const string& cols) { oss << "SELECT " << cols; return *this; }
    QueryBuilder& from(const string& table) { oss << " FROM " << table; return *this; }
    QueryBuilder& where(const string& cond) { oss << " WHERE " << cond; return *this; }
    string build() { return oss.str(); }
};

int main() {
    string q = QueryBuilder().select("name, age").from("users").where("age > 18").build();
    cout << q << endl;
    return 0;
}
